#include <iostream>

int main() {
    // Input contains:
    // Line 1: Word Hello
    // Line 2: Second Line
    char buf1[30];
    char buf2[30];

    // 1. cin >> stops at whitespace
    std::cin >> buf1;
    std::cout << "cin >> read: [" << buf1 << "]\n";

    // 2. cin.get reads remainder of line, leaves '\n' in stream
    std::cin.get(buf2, 30);
    std::cout << "cin.get read: [" << buf2 << "]\n";

    // 3. Remove lingering newline left by cin.get
    int lingering = std::cin.get();
    std::cout << "Lingering char ASCII: " << lingering << "\n";

    // 4. cin.getline consumes and discards the delimiter
    char lineBuf[50];
    std::cin.getline(lineBuf, 50);
    std::cout << "cin.getline read: [" << lineBuf << "]\n";

    // 5. Using cout.put
    std::cout << "Output via cout.put: ";
    std::cout.put('O').put('K').put('\n');

    return 0;
}

#include <iostream>

int main() {
    // Input contains: #12345RawBinaryData
    // 1. Check first character with peek()
    char nextChar = static_cast<char>(std::cin.peek());
    std::cout << "Peeked character: " << nextChar << "\n";

    // 2. Consume the '#' prefix
    char hashSymbol;
    std::cin.get(hashSymbol);

    // 3. Put back another character to inspect rollback mechanics
    std::cin.putback('@');
    char rolledBack;
    std::cin.get(rolledBack);
    std::cout << "Read after putback: " << rolledBack << "\n";

    // 4. Ignore digits up to 5 characters
    std::cin.ignore(5);

    // 5. Unformatted raw read into buffer
    char rawBuffer[30];
    std::cin.read(rawBuffer, 9); // read 9 characters: "RawBinary"
    std::streamsize bytesRead = std::cin.gcount();

    std::cout << "Bytes extracted by read: " << bytesRead << "\n";
    std::cout << "Content written via cout.write: [";
    std::cout.write(rawBuffer, bytesRead);
    std::cout << "]\n";

    return 0;
}
